//! Cash economics of a fill, per product. This is the only place that knows
//! what `Trade.price` and `Trade.quantity` mean for each instrument, so the
//! book and P&L layers can stay product-agnostic.
//!
//! Sign convention: cash the holder RECEIVES is positive.

use crate::bond::cashflows;
use chrono::NaiveDate;
use fd_types::{Instrument, Trade};

/// Signed cash generated by `t` on `inst`, settling on `settle`.
pub fn trade_cash(inst: &Instrument, t: &Trade, settle: NaiveDate) -> f64 {
    let q = t.signed_quantity();
    match inst {
        // quantity = face, price = clean per 100: pay dirty proceeds
        Instrument::TreasuryBond(b) => {
            let accrued = cashflows(b, settle).accrued;
            -q * (t.price + accrued) / b.face
        }
        // quantity = contracts, price = futures price per 100.
        // Cash-equivalent model: book the full notional price so PV + cash =
        // (price_now − price_trade) × size/100 × qty, i.e. cumulative variation margin.
        Instrument::BondFuture(f) => -q * t.price / 100.0 * f.contract_size,
        // quantity = notional, price = fixed rate: no cash at inception. An
        // off-market rate shows up as day-1 PV, which is correct.
        Instrument::OvernightSwap(_) => 0.0,
        // quantity = notional, price = premium per unit notional
        Instrument::Swaption(_) => -q * t.price,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use fd_types::*;

    fn trade(side: Side, qty: f64, px: f64) -> Trade {
        Trade { id: TradeId::new(), instrument: "X".into(), side, quantity: qty, price: px, cash: 0.0,
                ts: chrono::Utc::now(), trader: "t".into(), book: "B".into() }
    }

    #[test]
    fn bond_cash_is_dirty_proceeds_per_100() {
        let b = TreasuryBond { coupon: 0.04, issue_date: NaiveDate::from_ymd_opt(2026, 8, 15).unwrap(),
            maturity: NaiveDate::from_ymd_opt(2036, 8, 15).unwrap(), frequency: Frequency::SemiAnnual,
            day_count: DayCount::ActAct, face: 100.0 };
        let settle = NaiveDate::from_ymd_opt(2026, 8, 15).unwrap(); // issue date: no accrued
        let c = trade_cash(&Instrument::TreasuryBond(b.clone()), &trade(Side::Buy, 1_000_000.0, 99.0), settle);
        assert!((c + 990_000.0).abs() < 1e-6, "{c}");
        let settle2 = NaiveDate::from_ymd_opt(2026, 11, 15).unwrap(); // ~3 months accrued ≈ 1.0 per 100
        let c2 = trade_cash(&Instrument::TreasuryBond(b), &trade(Side::Sell, 1_000_000.0, 99.0), settle2);
        assert!(c2 > 990_000.0 && c2 < 1_001_000.0, "{c2}");
    }

    #[test]
    fn swap_has_no_inception_cash_and_swaption_pays_premium() {
        let r = NaiveDate::from_ymd_opt(2026, 10, 16).unwrap();
        let s = OvernightSwap { index: "SOFR".into(), effective: r, maturity: r, fixed_rate: 0.04,
            fixed_leg: PayReceive::Receive, fixed_frequency: Frequency::Annual, fixed_day_count: DayCount::Act360,
            float_day_count: DayCount::Act360, payment_lag_days: 2 };
        assert_eq!(trade_cash(&Instrument::OvernightSwap(s.clone()), &trade(Side::Buy, 1e7, 0.04), r), 0.0);
        let o = Swaption { expiry: r, underlying: s, strike: 0.04, cash_settled: true };
        let c = trade_cash(&Instrument::Swaption(o), &trade(Side::Buy, 1e7, 0.0025), r);
        assert!((c + 25_000.0).abs() < 1e-6);
    }
}
